    /* 그리드 행 선택 */
    onGridSelect1: function(dataview, selected, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.grid1,
            records = grid.getStore().data.items,
            trueRecords = selected, // 선택한 row 들
            naviView = me.getView().up('navigationview');

        // 하나만 선택되었는지 체크
        if(trueRecords.length > 1){
            Ext.Msg.alert('알림', '하나만 선택할 수 있습니다.');
            return;
        }

        /* 화면이동 */
        if (trueRecords[0].data.available != null) {
            me.PUSH_VIEW(naviView, {
                menuId  : 'HrdCrsAply02M',
                title   : '연수과정신청',
                records : trueRecords,
                isSubView : true,
                parentView : me.getView()
            });
        }
    },

