    /* 탭 패널 아이템 클릭시 이벤트 */
    onMytabpanelActiveItemChange: function(sender, value, oldValue, eOpts) {
        var me = this,
            refs = me.getReferences(),
            vm = me.getViewModel();

        if(value.reference == 'tabCrs1'){ // 정규과정 신청 탭 클릭시
            vm.set('activeTab', 'tabCrs1');
            me.onSelect();
        }else if(value.reference == 'tabCrs2'){	// 상시과정 신청 탭 클릭시
            vm.set('activeTab', 'tabCrs2');
            me.onSelect();
        }
    },

