    onStoreLoad: function(store, records, successful, operation, eOpts) {
        var me = this;
        var refs = me.getReferences();
        var vm = me.getViewModel();

        var result = operation.getResponse().responseJson;

        // 연수정보
        if (result.stnInfo) {
            var stnInfo = result.stnInfo;

            vm.set('stnInfo', stnInfo);
            refs.stnNdpsPnt.setHtml(stnInfo.lowCrsPnt);
            refs.stnCmpPnt.setHtml(stnInfo.cmpCrsPnt);

            if(!Ext.isEmpty(stnInfo.strdt) && !Ext.isEmpty(stnInfo.edt)){
                var stnInfoTxt = refs.stnInfo.defaultText + " (" + stnInfo.strdt.substring(0, 4) + "-" + stnInfo.strdt.substring(4, 6) + " ~ " + stnInfo.edt.substring(0, 4) + "-" + stnInfo.edt.substring(4, 6) + ")";
                refs.stnInfo.setHtml(stnInfoTxt);
            }
        }
    }

